UPDATE consumed_message SET status='consumed', consumed_at=UTC_TIMESTAMP(3),
    last_error_code=NULL, last_error_message=NULL, updated_at=UTC_TIMESTAMP(3)
WHERE consumer=#{consumer} AND message_key=#{messageKey}

UPDATE consumed_message SET status=#{status}, attempts=attempts+1,
    last_error_code=#{errorCode}, last_error_message=#{errorMessage}, updated_at=UTC_TIMESTAMP(3)
WHERE consumer=#{consumer} AND message_key=#{messageKey}
